// REAL — curriculum content, kept separate from gameplay code.
// Each skill: [id, subject, band, name, objective, prerequisites, explanation, alternate explanation, world locations].
// Each generator returns an activity:
//   { type: 'choice'|'number'|'order'|'sort'|'write'|'budget'|'trace', skill, q, ..., why }
// `why` is the worked explanation shown after every answer ("4 + 6 = 10, then add 3 to get 13").
// Generators are pure (no DOM), so tests/curriculum.test.mjs can validate every one of them.

import { MORE_SKILLS, MORE_GEN } from './curriculum2.js';
