  'read.summarize': [() => ch('read.summarize', 'Which is the best summary?', 'Fresh Mart is adding late hours on weekends and needs more evening staff.', ['Fresh Mart sells groceries.', 'Rosa likes Saturdays.', 'Staff must wear green aprons and name tags.'], 'A summary keeps the main point (new late weekend hours) and the key consequence (more evening staff). Uniform details are extras.', doc('MEMO', ['Starting next month, Fresh Mart will stay open until midnight on Fridays and Saturdays.', 'We need four more evening cashiers.', 'As always, wear your green apron and name tag.']))],
  'read.contracts': [() => { const fee = pick([25, 40, 60]), days = pick([3, 5, 7]); return ch('read.contracts', `Rent is due on the 1st. You pay on the ${days + 3}th. What happens?`, `You owe a $${fee} late fee`, ['Nothing, it is within the grace period', 'You are evicted immediately', `You owe $${fee * 2}`], `The contract allows ${days} days of grace. Paying on day ${days + 3} is after the grace period, so the $${fee} fee applies. It doesn’t say anything about eviction for one late payment.`, doc('RENTAL AGREEMENT', ['Rent is due on the 1st of each month.', `A grace period of ${days} days applies.`, `After the grace period, a $${fee} late fee is charged.`])); }],
