  'read.sources': [() => ch('read.sources', 'Which source is most trustworthy for flu-season advice?', 'A City Clinic guide from this year written by nurses', ['A stranger’s post from 8 years ago', 'An ad for a vitamin drink', 'Jax’s cousin'], 'It is current, written by experts, and the clinic has no product to sell you.')],
