  'write.report': [() => ch('write.report', 'Which sentence belongs in the “recommendation” part of a report?', 'We should order 20% more milk on weekends.', ['Milk sold out three Saturdays in a row.', 'Milk is white.', 'I like milk.'], 'Findings say what happened (milk sold out). A recommendation says what to do next (order more).')],
  'write.persuasive': [() => ({ type: 'write', skill: 'write.persuasive', q: 'Convince Rosa to add a recycling bin by the door. Give a reason and some evidence.', rubric: [['States what you want', /\b(recycl\w*|bins?)\b/i], ['Gives a reason', /\b(because|so that|this would|it would|since)\b/i], ['Uses evidence or a benefit', /\b(customers|cans|bottles|waste|save|clean|every day|\d)\b/i], ['Polite tone', (t) => !/\b(stupid|dumb|must now)\b/i.test(t)]], minWords: 15, model: 'Could we add a recycling bin by the door? I think it would help because customers leave about 20 cans a day in the trash. Recycling them would keep the store cleaner.' })],
